<template><view class="page"><view class="hero"><text class="eyebrow">我的任务</text><text class="title">后台进度，随时掌握</text><text class="subtitle">知识库解析等耗时操作会显示在这里。</text></view><view v-if="loading" class="loading">正在读取任务…</view><view v-else-if="!tasks.length" class="empty card"><text class="empty-title">暂无后台任务</text><text>上传知识库资料后，任务会显示在这里。</text></view><view v-for="item in tasks" :key="item.id" class="card"><view class="row between"><text class="card-title">{{item.task_type==='knowledge.process'?'知识库文件处理':item.task_type}}</text><text :class="['badge',item.status]">{{statusText[item.status]||item.status}}</text></view><view class="progress"><view :style="{width:`${item.progress||0}%`}"></view></view><view class="row between"><text class="muted">第 {{item.attempt_count}}/{{item.max_attempts}} 次</text><text>{{item.progress||0}}%</text></view><text v-if="item.error_message" class="error">{{item.error_message}}</text><button v-if="['failed','canceled'].includes(item.status)" class="secondary retry" @click="retry(item)">重新执行</button></view></view></template>
<script setup>import{ref}from'vue';import{onShow,onHide}from'@dcloudio/uni-app';import{api,requireLogin}from'../../api';const tasks=ref([]),loading=ref(true),statusText={queued:'排队中',running:'执行中',completed:'已完成',failed:'失败',canceled:'已取消'};let timer;async function load(){if(!requireLogin())return;try{tasks.value=await api.tasks()}catch(e){uni.showToast({title:e.message,icon:'none'})}finally{loading.value=false}clearInterval(timer);if(tasks.value.some(v=>['queued','running'].includes(v.status)))timer=setInterval(load,3500)}async function retry(item){try{const next=await api.retryTask(item.id);tasks.value=tasks.value.map(v=>v.id===item.id?next:v);load()}catch(e){uni.showToast({title:e.message,icon:'none'})}}onShow(load);onHide(()=>clearInterval(timer))</script>
<style scoped>.progress{height:14rpx;background:#eee6da;border-radius:20rpx;overflow:hidden;margin:24rpx 0 14rpx}.progress view{height:100%;background:#a94439}.error{display:block;color:#a53d35;font-size:22rpx;margin-top:15rpx}.retry{margin-top:20rpx}</style>
